3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
8	
9	/**
10	 * Rejects a create-owner request whose lower-cased email is already used by any other owner.
11	 * Runs after {@link ValidateOwnerFields} has lower-cased the body's email, and compares it against
12	 * every existing owner's email (lower-cased the same way). A request without an email is left alone.
13	 * Throws {@link DuplicateEmailException} (handled as 409) on a collision.
14	 */
15	public class CheckOwnerEmailUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateEmailException {
19	        String email = request.getEmail();
20	        if (email == null || email.isBlank()) {
21	            return;
22	        }
23	        String normalized = email.toLowerCase();
24	        for (Owner existing : ownerRepository.findAll()) {
25	            String existingEmail = existing.getEmail();
26	            if (existingEmail != null && normalized.equals(existingEmail.toLowerCase())) {
27	                throw new DuplicateEmailException(request.getEmail());
28	            }
29	        }
30	    }
31	}
