1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request that shares both last name and address with an existing owner.
11	 * Last name and address are each compared case-insensitively with runs of whitespace collapsed to a
12	 * single space (and leading/trailing whitespace trimmed). Throws {@link DuplicateHouseholdException}
13	 * (handled as 409) on a collision, unless the request opted in with {@code sharesHousehold: true}.
14	 */
15	public class CheckOwnerHouseholdUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        // The request may opt out of the household-uniqueness rule.
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (OwnerHousehold.sameHousehold(request.getLastName(), request.getAddress(),
25	                    existing.getLastName(), existing.getAddress())) {
26	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
27	            }
28	        }
29	    }
30	}
