1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns a shared {@code householdId} when the request opted in with {@code sharesHousehold: true}
10	 * and another owner already shares the same last name and address. The new owner and every existing
11	 * household member receive the same stable identifier (see {@link OwnerHousehold#id}), so joiners
12	 * converge on one value. Runs after {@link BuildOwner}, so the built owner is available to stamp.
13	 * When nobody else is in the household there is no one to share with, so the id is left null.
14	 */
15	public class AssignHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
18	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
19	            return;
20	        }
21	        boolean hasHousehold = false;
22	        String householdId = OwnerHousehold.id(request.getLastName(), request.getAddress());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (OwnerHousehold.sameHousehold(request.getLastName(), request.getAddress(),
25	                    existing.getLastName(), existing.getAddress())) {
26	                hasHousehold = true;
27	                // Back-fill members that predate the household so every member shares the id.
28	                if (existing.getHouseholdId() == null) {
29	                    existing.setHouseholdId(householdId);
30	                    ownerRepository.save(existing);
31	                }
32	            }
33	        }
34	        if (hasHousehold) {
35	            owner.setHouseholdId(householdId);
36	        }
37	    }
38	}
