1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
8	
9	/**
10	 * Shared telephone handling for the owner pipelines. Telephone numbers are stored in E.164 form:
11	 * a leading {@code '+'} and country code are kept when present; otherwise country code {@code +61}
12	 * is assumed and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes
13	 * and brackets are stripped, and the result must carry 8 to 15 digits after the {@code '+'}. So
14	 * {@code "0412 345 678"} is stored as {@code "+61412345678"}. For known country codes the national
15	 * number (the digits after the country code) must have the exact expected length: {@code '+61'}
16	 * requires 9 national digits and {@code '+1'} requires 10. A number that cannot form valid E.164 is
17	 * rejected with {@link InvalidOwnerTelephoneException} (handled as 400).
18	 */
19	final class OwnerTelephone {
20	
21	    /** Assumed country code when the input carries no leading '+'. */
22	    private static final String DEFAULT_COUNTRY_CODE = "+61";
23	
24	    /** Known country codes (leading '+' included) to their required national-number length. */
25	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("+61", 9, "+1", 10);
26	
27	    /** Spaces, dashes and brackets are removed before parsing. */
28	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
29	
30	    private static final Pattern DIGITS = Pattern.compile("\\d+");
31	
32	    private OwnerTelephone() {
33	    }
34	
35	    /**
36	     * Normalizes the telephone on the request in place to its E.164 form, or throws when the value
37	     * cannot form a valid E.164 number.
38	     */
39	    static void normalize(OwnerFieldsDto request) throws InvalidOwnerTelephoneException {
40	        request.setTelephone(toE164(request.getTelephone()));
41	    }
42	
43	    /**
44	     * Converts a raw telephone to E.164, or throws {@link InvalidOwnerTelephoneException} when it
45	     * cannot form a valid E.164 number.
46	     */
47	    static String toE164(String raw) throws InvalidOwnerTelephoneException {
48	        if (raw == null) {
49	            throw new InvalidOwnerTelephoneException(null);
50	        }
51	        String cleaned = SEPARATORS.matcher(raw).replaceAll("");
52	        String e164;
53	        if (cleaned.startsWith("+")) {
54	            // Explicit country code: keep the '+' and everything after it, which must be digits.
55	            String digits = cleaned.substring(1);
56	            if (!DIGITS.matcher(digits).matches()) {
57	                throw new InvalidOwnerTelephoneException(raw);
58	            }
59	            e164 = "+" + digits;
60	        }
61	        else {
62	            // No country code: assume +61 and drop a single leading '0' from the national digits.
63	            if (!DIGITS.matcher(cleaned).matches()) {
64	                throw new InvalidOwnerTelephoneException(raw);
65	            }
66	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
67	            e164 = DEFAULT_COUNTRY_CODE + national;
68	        }
69	        int digitCount = e164.length() - 1;
70	        if (digitCount < 8 || digitCount > 15) {
71	            throw new InvalidOwnerTelephoneException(raw);
72	        }
73	        // For known country codes, the national number must have the exact expected length.
74	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
75	            String countryCode = entry.getKey();
76	            if (e164.startsWith(countryCode)) {
77	                int nationalLength = e164.length() - countryCode.length();
78	                if (nationalLength != entry.getValue()) {
79	                    throw new InvalidOwnerTelephoneException(raw);
80	                }
81	                break;
82	            }
83	        }
84	        return e164;
85	    }
86	
87	    /**
88	     * Best-effort E.164 form for comparison, returning {@code null} when the value cannot form a
89	     * valid E.164 number. Used to compare an existing owner's stored telephone against a request.
90	     */
91	    static String toE164OrNull(String raw) {
92	        try {
93	            return toE164(raw);
94	        }
95	        catch (InvalidOwnerTelephoneException ex) {
96	            return null;
97	        }
98	    }
99	}
