1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.regex.Pattern;
7	
8	/**
9	 * Shared household rules for the create-owner pipeline. Two owners belong to the same household
10	 * when their last name and address match after normalization (case-insensitive, with runs of
11	 * whitespace collapsed to a single space and leading/trailing whitespace trimmed). The household
12	 * identifier is a stable value derived from that same normalized last name and address, so every
13	 * owner in a household resolves to the same id without coordination.
14	 */
15	final class OwnerHousehold {
16	
17	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
18	
19	    private OwnerHousehold() {
20	    }
21	
22	    static String normalize(String value) {
23	        if (value == null) {
24	            return "";
25	        }
26	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase();
27	    }
28	
29	    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
30	        return normalize(lastNameA).equals(normalize(lastNameB))
31	                && OwnerAddress.normalize(addressA).equals(OwnerAddress.normalize(addressB));
32	    }
33	
34	    /** Stable identifier for the household of the given last name and address. */
35	    static String id(String lastName, String address) {
36	        String key = normalize(lastName) + "�" + OwnerAddress.normalize(address);
37	        return "HH-" + sha256hex(key).substring(0, 12).toUpperCase();
38	    }
39	
40	    private static String sha256hex(String value) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
43	            StringBuilder sb = new StringBuilder(digest.length * 2);
44	            for (byte b : digest) {
45	                sb.append(String.format("%02x", b));
46	            }
47	            return sb.toString();
48	        }
49	        catch (NoSuchAlgorithmException e) {
50	            throw new IllegalStateException("SHA-256 unavailable", e);
51	        }
52	    }
53	}
