1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
7	
8	/**
9	 * Shared email handling for the owner pipelines. An owner may include an {@code email}: when present
10	 * it must be a syntactically valid address, and is stored and returned lower-cased. When absent (null
11	 * or blank) it is left unset. An invalid address is rejected with {@link InvalidOwnerEmailException}.
12	 */
13	final class OwnerEmail {
14	
15	    /** WHATWG "valid email address" syntax — a widely accepted syntactic check. */
16	    private static final Pattern EMAIL = Pattern.compile(
17	            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+"
18	                    + "@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
19	                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
20	
21	    private OwnerEmail() {
22	    }
23	
24	    /**
25	     * Validates and normalizes the email on the request in place: a present, non-blank email is
26	     * trimmed, checked for syntax and lower-cased; a null or blank email is left unchanged.
27	     */
28	    static void normalize(OwnerFieldsDto request) throws InvalidOwnerEmailException {
29	        String email = request.getEmail();
30	        if (email == null || email.isBlank()) {
31	            return;
32	        }
33	        String trimmed = email.trim();
34	        if (!EMAIL.matcher(trimmed).matches()) {
35	            throw new InvalidOwnerEmailException(email);
36	        }
37	        request.setEmail(trimmed.toLowerCase());
38	    }
39	}
