1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Runs first in the create-owner pipeline. Rejects a request that is missing or blank in any of
15	 * firstName, lastName, address, city or telephone by throwing {@link MissingOwnerFieldsException}
16	 * with the names of every offending field. Otherwise it publishes the body for later steps.
17	 */
18	public class ValidateOwnerFields {
19	
20	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
21	            throws MissingOwnerFieldsException, InvalidOwnerEmailException, InvalidOwnerTelephoneException {
22	        // Normalize the address before the required-field check, so an address that is blank after
23	        // normalization is rejected and later steps see (and store) the canonical form.
24	        OwnerAddress.normalize(request);
25	        List<String> missing = new ArrayList<>();
26	        if (isBlank(request.getFirstName())) {
27	            missing.add("firstName");
28	        }
29	        if (isBlank(request.getLastName())) {
30	            missing.add("lastName");
31	        }
32	        if (isBlank(request.getAddress())) {
33	            missing.add("address");
34	        }
35	        if (isBlank(request.getCity())) {
36	            missing.add("city");
37	        }
38	        if (isBlank(request.getTelephone())) {
39	            missing.add("telephone");
40	        }
41	        if (!missing.isEmpty()) {
42	            throw new MissingOwnerFieldsException(missing);
43	        }
44	        // Store the telephone in E.164 form; reject a number that cannot form valid E.164.
45	        OwnerTelephone.normalize(request);
46	        // An owner may include an email; when present it must be valid and is stored lower-cased.
47	        OwnerEmail.normalize(request);
48	        validated.set(request);
49	    }
50	
51	    private static boolean isBlank(String value) {
52	        return value == null || value.isBlank();
53	    }
54	}
