5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	public class BuildOwner {
10	
11	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
12	        Owner owner = ownerMapper.toOwner(request);
13	        // The effective registration date — supplied or defaulted to the server date — must fall on
14	        // a business day, so a weekend date rolls forward to the next Monday. Everything derived from
15	        // the registration date (e.g. the membership number's year segment) then uses this value.
16	        owner.setRegistrationDate(BusinessDay.effective(owner.getRegistrationDate()));
17	        built.set(owner);
18	    }
19	}
