7	/**
8	 * Assigns the {@code customerCode} to a newly built owner, formatted
9	 * {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the upper-cased first three letters of
10	 * the owner's city, LAST3 the upper-cased first three letters of the owner's last name
11	 * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
12	 * owners already in that city (e.g. {@code SYD-SMI-0007}). Runs before the owner is
13	 * saved, so the count excludes the owner being created.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city = owner.getCity();
19	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
20	        String lastName = owner.getLastName();
21	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
22	        int sequence = (int) ownerRepository.findAll().stream()
23	            .filter(o -> city.equalsIgnoreCase(o.getCity()))
24	            .count() + 1;
25	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
26	    }
27	}
