3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day rules for an owner's registration date. The effective registration date — whether
8	 * supplied in the request or defaulted to the server date — must fall on a business day: a Saturday
9	 * or Sunday rolls forward to the following Monday. Everything derived from the registration date
10	 * (the membership number's year segment, the daily create-limit) uses this adjusted date.
11	 */
12	final class BusinessDay {
13	
14	    private BusinessDay() {
15	    }
16	
17	    /**
18	     * Rolls a weekend date forward to the next Monday; a weekday is returned unchanged.
19	     */
20	    static LocalDate adjust(LocalDate date) {
21	        DayOfWeek dayOfWeek = date.getDayOfWeek();
22	        if (dayOfWeek == DayOfWeek.SATURDAY) {
23	            return date.plusDays(2);
24	        }
25	        if (dayOfWeek == DayOfWeek.SUNDAY) {
26	            return date.plusDays(1);
27	        }
28	        return date;
29	    }
30	
31	    /**
32	     * The effective, business-day-adjusted registration date: the supplied date when present,
33	     * otherwise the server's current date, rolled off any weekend to the next Monday.
34	     */
35	    static LocalDate effective(LocalDate supplied) {
36	        LocalDate base = (supplied != null) ? supplied : LocalDate.now();
37	        return adjust(base);
38	    }
39	}
