9	 * {@code bulkSignupWarning} is true once <em>more than 80</em> owners share the given (business-day
10	 * adjusted) registration date, otherwise false. Shares the same accumulation path as the daily
11	 * create-limit rule ({@link CheckOwnerDailyLimit}), which caps the same day at 100.
12	 */
13	final class BulkSignup {
14	
15	    private static final int WARNING_THRESHOLD = 80;
16	
17	    private BulkSignup() {
18	    }
19	
20	    /**
21	     * Whether more than 80 owners already carry the effective business day of {@code registrationDate}.
22	     */
23	    static boolean warning(LocalDate registrationDate, OwnerRepository ownerRepository) {
24	        LocalDate day = BusinessDay.effective(registrationDate);
25	        long count = ownerRepository.findAll().stream()
26	            .filter(o -> day.equals(o.getRegistrationDate()))
27	            .count();
28	        return count > WARNING_THRESHOLD;
29	    }
